import{nextStep}from'./workflow.js?v=db3d55b76c6a82dc';
import{scanFolder,importPapers}from'./folder-import.js?v=db3d55b76c6a82dc';
import{Workspace,writeFile,maybeJSON}from'./storage.js?v=db3d55b76c6a82dc';import{extractPDF}from'./pdf.js?v=db3d55b76c6a82dc';import{safeUrl,digest,SECTION_LABELS,fingerprint,reportMarkdown}from'./core.js?v=db3d55b76c6a82dc';import{listModels,analyzePaper,synthesize,generate}from'./analysis.js?v=db3d55b76c6a82dc';import{zip}from'./zip.js?v=db3d55b76c6a82dc';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let ws=null,professors=[],selected=null,view='library',tab='papers',query='',edit=null,busy=false,controller=null,config={key:'',model:''},models=[],pdfURL='',currentResult=null,renderSeq=0;const content=$('#content');const current=()=>professors.find(p=>p.id===selected);function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').style.display='none',7000)}function link(u,t){return safeUrl(u)?`<a href="${esc(safeUrl(u))}" target="_blank" rel="noopener noreferrer">${esc(t)} ↗</a>`:'<span class="hint">未提供來源連結</span>'}function download(name,data,type='text/plain'){let u=URL.createObjectURL(data instanceof Blob?data:new Blob([data],{type})),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
function progress(t){$('#jobText').textContent=t}async function job(label,fn){if(busy)return;busy=true;controller=new AbortController();$('#job').hidden=false;progress(label);document.querySelectorAll('.nav,#connect,#refresh').forEach(x=>x.disabled=true);try{await fn(controller.signal);await render()}catch(e){toast(e.message);if(ws){try{professors=await ws.list();await render()}catch{}}}finally{busy=false;$('#job').hidden=true;document.querySelectorAll('.nav,#connect,#refresh').forEach(x=>x.disabled=false);controller=null}}
$('#cancelJob').onclick=()=>controller?.abort();$('#connect').onclick=async()=>{if(!window.showDirectoryPicker){toast('實體資料夾功能需要桌面 Chrome／Edge，請以獨立 HTTPS 頁面開啟。');return}try{let h=await window.showDirectoryPicker({mode:'readwrite',id:'scholar-atlas-v2'});await job('開啟實體資料夾…',async()=>{ws=await Workspace.open(h);professors=await ws.list();selected=null;view='library';$('#folderStatus').textContent=h.name+'/scholar-atlas-data/';$('#connect').textContent='切換資料夾';$('#refresh').hidden=false})}catch(e){if(e.name!=='AbortError')toast('無法開啟資料夾：'+e.message)}};$('#refresh').onclick=()=>job('重新讀取資料…',async()=>{professors=await ws.list();if(!current())selected=null;toast('已重新讀取磁碟資料')});document.querySelectorAll('.nav').forEach(b=>b.onclick=()=>{if(busy)return;view=b.dataset.view;if(view!=='model')selected=null;render()});$('#closeDialog').onclick=$('#cancel').onclick=()=>{if(!busy)$('#editor').close()};$('#editor').addEventListener('cancel',e=>{if(busy)e.preventDefault()});$('#closeEvidence').onclick=()=>{$('#evidence').close();if(pdfURL)URL.revokeObjectURL(pdfURL);pdfURL=''};
async function render(){let seq=++renderSeq;document.querySelectorAll('.nav').forEach(b=>b.classList.toggle('active',b.dataset.view===view));$('#modelStatus').textContent=config.key&&config.model?'模型已選擇：'+config.model:'模型尚未設定';$('#crumb').textContent=view==='library'?(current()?.name||'我的教授'):({model:'AI 設定',guide:'使用說明'}[view]);if(view==='model')return modelView();if(view==='guide')return guide();if(current())return detail(seq);library()}
function library(){if(!ws){content.innerHTML=`<section class="hero"><div><div class="eyebrow">YOUR PAPERS → YOUR RESEARCH BRIEF</div><h1>從一個教授資料夾開始。</h1><p>放入論文 PDF，整理研究方向，為申請與聯絡教授做好準備。</p></div></section><div class="panel welcome"><span class="badge green">第一步 · 不需要 API 金鑰</span><h2 style="margin-top:20px">匯入一位教授的論文</h2><p>選一個裝有 PDF 的資料夾，子資料夾也會一起讀取。<br>確認教授名稱後，自動建立論文清單，不用逐篇新增。</p><button class="primary" data-act="import-folder">選取教授資料夾，開始匯入</button><p class="hint">將一位教授的論文 PDF 放在同一個資料夾。名稱與標題可在匯入後修改。<br>原始 PDF 留在電腦，不會因匯入而上傳到 AI。</p></div><div class="panel resume-panel"><div><h3>之前已經用過？</h3><p>選取先前的 scholar-atlas-data，或它的父資料夾，恢復教授與分析紀錄。</p></div><button data-act="connect">開啟既有研究庫</button></div><div class="steps"><div><b>1　匯入資料夾</b><p>建立教授與論文清單。無金鑰也能閱讀 PDF、編輯資料、保存與匯出。</p></div><div><b>2　分析原文</b><p>輸入自己的 Gemini 金鑰，確認傳送文字後產生逐篇分析。</p></div><div><b>3　整理研究概要</b><p>至少完成兩篇分析，再結合申請方向統整並回查引用。</p></div></div><p class="hint">請用桌面 Chrome／Edge 直接開啟網站。首次匯入會在所選資料夾內建立 scholar-atlas-data。網站不附共用 API 金鑰，也不預填分析結果。</p>`;return}let total=professors.reduce((a,p)=>a+p.papers.length,0),done=professors.reduce((a,p)=>a+p.papers.filter(q=>q.analysisAt).length,0);content.innerHTML=`<section class="hero"><div><div class="eyebrow">YOUR RESEARCH LIBRARY</div><h1>教授與原文資料庫</h1><p>資料直接保存在你的電腦；模型分析只在你按下按鈕並同意後執行。</p></div><div class="actions"><button class="primary" data-act="import-folder">匯入教授資料夾</button><button data-act="add-prof">＋ 新增教授</button></div></section><div class="stats"><div class="stat"><div class="stat-icon">▱</div><div><strong>${professors.length}</strong><small>實體教授目錄</small></div></div><div class="stat"><div class="stat-icon">▤</div><div><strong>${total}</strong><small>論文與來源</small></div></div><div class="stat"><div class="stat-icon">✓</div><div><strong>${done}</strong><small>已完成原文分析</small></div></div></div><div class="toolbar"><input id="search" aria-label="搜尋教授" placeholder="搜尋教授、學校、Program" value="${esc(query)}"></div><div class="grid" id="cards"></div><section class="panel"><h3>我的申請研究方向</h3><p>跨論文分析會依這段內容說明關聯與可能的研究問題。</p><textarea id="interests" aria-label="申請研究方向" placeholder="例如：結合運籌最佳化與機器學習，研究受限制的決策問題。">${esc(ws.settings.interests)}</textarea><button style="margin-top:12px" data-act="save-interests">儲存研究方向</button></section>`;cards();$('#search').oninput=e=>{query=e.target.value;cards()}}
function cards(){$('#cards').innerHTML=professors.filter(p=>[p.name,p.school,p.program].join(' ').toLowerCase().includes(query.toLowerCase())).map(p=>`<article class="card"><div class="card-top"><div class="avatar">${esc(p.name.slice(0,2))}</div><span class="badge green">磁碟目錄</span></div><h2>${esc(p.name)}</h2><div class="school">${esc(p.school)} · ${esc(p.program)}</div><p>${p.papers.filter(q=>q.hasPDF).length} 份原文 PDF<br>${p.papers.filter(q=>q.analysisAt).length} 篇有可回查的分析</p><div class="card-bottom"><span>▤ ${p.papers.length} 篇論文</span><button data-act="open" data-id="${esc(p.id)}">開啟資料夾 →</button></div></article>`).join('')+`<button class="card add-card" data-act="add-prof"><span class="plus">＋</span><h3>新增一位教授</h3><p>不預填研究方向或論文<br>從你的原始資料開始</p></button>`}
async function detail(seq){let p=current();content.innerHTML=`<section class="hero"><div><div class="eyebrow"><a href="#" data-act="back">← 教授資料夾</a></div><h1>${esc(p.name)}</h1><p>${esc(p.school)} · ${esc(p.program)}　${link(p.url,'官方頁面')}</p><small class="hint">professors/${esc(p.folder)}/</small></div><div class="actions"><button class="primary" data-act="add-paper">＋ 加入 PDF／來源</button><details class="more-actions"><summary>教授資料與匯出</summary><button data-act="edit-prof">編輯教授資料</button><button data-act="zip">下載完整資料夾 ZIP</button></details></div></section>${workflowPanel(p)}<div class="tabs">${[['papers','論文與逐篇分析'],['synthesis','研究概要'],['notes','申請筆記']].map(([k,n])=>`<button data-act="tab" data-id="${k}" class="${tab===k?'selected':''}">${n}</button>`).join('')}</div><div id="detailBody"></div>`;let d=$('#detailBody');if(tab==='papers'){d.innerHTML=`<div class="panel"><h2>論文與原文分析</h2>${[...p.papers].sort((a,b)=>(b.year||0)-(a.year||0)).map(q=>`<article class="paper"><div class="year">${esc(q.year||'未填')}</div><div><h3>${esc(q.title)}</h3><span class="badge ${q.analysisAt?'green':''}">${q.analysisAt?'已分析 · '+q.analysisCount+' 條主張':q.hasPDF?'已讀取 '+q.pageCount+' 頁':'僅來源連結'}</span><p>${q.hasPDF?`PDF：${esc(q.originalName)}${q.lowPages?.length?' · '+q.lowPages.length+' 頁文字稀少':''}`:'尚未提供原文，不能進行原文分析。'}</p>${link(q.url,'論文來源')}<p class="hint">ID：${esc(q.id)}</p></div><div class="actions paper-actions"><button data-act="edit-paper" data-id="${esc(q.id)}">編輯資料／補上 PDF</button>${q.hasPDF?`<button data-act="read" data-id="${esc(q.id)}">閱讀原文</button><button class="primary" data-act="analyze" data-id="${esc(q.id)}">${q.analysisAt?'重新分析':'分析原文'}</button>`:''}${q.analysisAt?`<button data-act="analysis" data-id="${esc(q.id)}">查看分析</button>`:''}<button class="danger" data-act="archive-paper" data-id="${esc(q.id)}">移到封存</button></div></article>`).join('')||'<div class="empty">尚未加入論文。新增資料時可附上有權使用的 PDF，或先保存來源連結。</div>'}</div><p class="hint">圖表與圖片不會被文字擷取完整讀取。掃描 PDF 需先 OCR；任何分析都會標示文字缺口。</p><button class="danger" data-act="archive-prof">封存教授資料夾</button>`}else if(tab==='notes'){d.innerHTML=`<div class="panel"><h2>我的申請筆記</h2><p>記錄你確實閱讀的內容、研究經驗與想向教授提問的問題。此欄為你的筆記，不會冒稱為模型分析。</p><textarea id="notes" style="min-height:300px" aria-label="申請筆記">${esc(p.notes||'')}</textarea><button class="primary" data-act="save-notes">儲存筆記</button></div>`}else{d.innerHTML='<div class="panel">讀取已儲存概要…</div>';let result=await ws.synthesis(p);if(seq!==renderSeq)return;currentResult=result;let available=p.papers.filter(q=>q.analysisAt);d.innerHTML=`<div class="panel"><h2>跨論文研究分析</h2><p>以已完成原文分析的論文為材料，歸納主軸、研究演進、共同方法與申請方向關聯。每條結論保留可回查的原文引用。</p><label class="field">你的申請研究方向<textarea id="interests" placeholder="例如：運籌最佳化與機器學習、供應鏈決策。">${esc(ws.settings.interests)}</textarea></label><button data-act="save-interests">儲存申請方向</button><p class="hint">先儲存方向，再勾選至少兩篇論文產生概要。方向可留空，但不會有個人化契合依據。</p><div class="selection">${available.map(q=>`<label><input type="checkbox" name="selectedPaper" value="${esc(q.id)}" checked> ${esc(q.title)} (${q.year||'年份未填'})</label>`).join('')||'<p>請先完成至少兩篇論文的原文分析。</p>'}</div><button class="primary" data-act="synthesize" ${available.length<2?'disabled':''}>分析所選論文</button></div>${result?`${result.fingerprint!==fingerprint(p,ws.settings.interests)?'<div class="notice warning">資料或申請方向已更新；以下是先前保存的概要，請重新分析。</div>':''}<div class="actions"><button data-act="download-synthesis">↓ 下載概要 Markdown</button></div>${reportHTML(result,p.papers)}`:''}`}}
function reportHTML(r,papers){return `<div class="notice"><b>來源可回查，不代表結論已人工驗證。</b><br>模型：${esc(r.model)} · ${esc(new Date(r.createdAt).toLocaleString('zh-TW',{timeZone:'Asia/Taipei'}))}<br>${esc(r.coverage)}<br>引文核對未通過而排除的主張：${r.rejected?.length||0}</div>`+Object.entries(SECTION_LABELS).map(([k,n])=>{let claims=r.claims.filter(c=>c.section===k);return claims.length?`<section class="panel"><h2>${n}</h2>${claims.map(c=>`<div class="claim"><span class="badge ${c.kind==='evidence'?'green':''}">${c.kind==='evidence'?'依原文整理':'推論／建議'}</span><p>${esc(c.text)}</p><div class="citations">${c.citations.map(ref=>`<button data-act="cite" data-id="${esc(ref.paperId)}" data-page="${ref.page}" data-quote="${esc(ref.quote)}">${esc(papers.find(q=>q.id===ref.paperId)?.title||ref.paperId)} · PDF p.${ref.page} ↗</button>`).join('')}</div></div>`).join('')}</section>`:''}).join('')+`<div class="panel"><h3>涵蓋範圍與限制</h3><p class="pre">${esc(r.gaps||'未另列')}</p><p class="hint">頁碼為 PDF 檔案實際頁次，不一定等於論文印刷頁碼；圖表、公式與雙欄排版可能影響文字完整性。</p></div>`}
function modelView(){content.innerHTML=`<section class="hero"><div><div class="eyebrow">REAL MODEL CONNECTION</div><h1>設定 AI，開始讀懂論文</h1><p>直接使用你的 Gemini API。沒有內建金鑰，也不以模板替代分析。</p></div></section><section class="panel"><h2>1 · 輸入你自己的 Gemini API 金鑰</h2><p>這不是 GitHub 密碼，也不是 ChatGPT 登入資訊。匯入、閱讀與保存 PDF 不需要金鑰。</p><p>金鑰只保存在此分頁記憶體，重新整理後需重填；不會寫入磁碟、GitHub 或網站伺服器。模型呼叫依你的 API 方案計費／限額。<br>只有在分析確認後，論文擷取文字、引用與研究興趣才會送至 Google Gemini。</p><p>${link('https://aistudio.google.com/apikey','在 Google AI Studio 取得 API 金鑰')}</p><label class="field">API Key<input id="apiKey" type="password" autocomplete="off" placeholder="輸入你自己的 Gemini API key"></label><div class="actions" style="margin-top:14px"><button data-act="verify-key" class="primary">驗證金鑰並載入可用模型</button><button data-act="clear-key">清除本分頁金鑰</button></div><p class="hint">${config.key?'此分頁已保留驗證過的金鑰；空白輸入框不代表金鑰已清除。':'尚未設定金鑰。請勿把金鑰貼進聊天或提交到 Repository。'}</p>${models.length?`<label class="field">2 · 選擇可用模型<select id="modelSelect">${models.map(m=>`<option ${config.model===m?'selected':''}>${esc(m)}</option>`).join('')}</select></label><button data-act="test-model" style="margin-top:14px">測試模型（選用）</button><p class="hint">測試只送出一小段連線測試文字，不包含研究資料；會產生一次 API 呼叫。</p>`:''}</section>${current()?`<section class="panel resume-panel"><div><h3>接著分析 ${esc(current().name)} 的論文</h3><p>${config.key&&config.model?'模型已選好。返回後可批次分析尚未處理的論文。':'先完成上方設定；也可隨時返回閱讀原文。'}</p></div><button class="primary" data-act="return-professor">返回教授，繼續分析 →</button></section>`:''}`;if($('#modelSelect'))$('#modelSelect').onchange=e=>{config.model=e.target.value;$('#modelStatus').textContent='模型已選擇：'+config.model}}
function guide(){content.innerHTML=`<section class="hero"><div><div class="eyebrow">A VERIFIABLE WORKFLOW</div><h1>從原文到研究概要</h1><p>沒有預填教授、示範論文或模擬分析結果。</p></div></section><div class="panel"><h2>使用順序</h2><ol><li>用桌面 Chrome／Edge 開啟網站，按「匯入教授資料夾」，選取內含 PDF 的一位教授目錄。</li><li>確認教授名稱與檔案保存權後，系統批次匯入 PDF；標題預設為檔名，可逐篇修改。亦可手動新增教授、論文與來源連結。</li><li>系統以 PDF.js 在本機逐頁擷取文字，保存 original.pdf 與 pages.json。</li><li>在 AI 設定輸入自己的 Gemini API key 並選擇模型；連線測試為選用。按「返回教授，繼續分析」回到原教授。</li><li>按下一步的「分析待處理論文」，一次確認傳送範圍後逐篇處理；也可只分析一篇。失敗時停止後續 API 呼叫，保留已完成結果。</li><li>按引用按鈕，回查 PDF 對應頁與擷取文字。</li><li>至少兩篇分析完成後，進入「研究概要」，儲存申請方向、勾選論文，再按「分析所選論文」。</li></ol></div><div class="panel"><h2>你的資料存在哪裡？</h2><p class="pre">scholar-atlas-data/workspace.json：申請研究方向\nprofessors/教授姓名-ID/profile.json：教授資料與論文清單\nprofessors/教授姓名-ID/papers/論文ID/original.pdf：原文\n同一論文目錄/pages.json：逐頁擷取文字\n同一論文目錄/analysis.json、analysis.md：附引用分析\n教授目錄/synthesis.json、synthesis.md：跨論文概要\n教授目錄/application-notes.md：申請筆記（儲存筆記後建立）\ntrash/：封存資料，可在電腦檔案總管取回</p><p>每次重新開啟網站可選原父資料夾，或直接選 scholar-atlas-data 研究庫。不使用 v1 的瀏覽器假資料。資料夾匯出 ZIP 會包含實際檔案。</p></div><div class="panel"><h2>明確限制</h2><p>不支援自動全網搜尋、付費論文繞過、掃描 PDF OCR 或圖表視覺理解。無文字頁面會標示缺口。API 中斷、引用核對失敗與輸出截斷均不會顯示完成。片段核對證明引文存在，不證明論述或推論正確。</p></div><div class="panel"><h2>作業與開發文件</h2><div class="doclinks"><a href="AGENTS.md" download>AGENTS.md ↓</a><a href="README.md" download>README ↓</a><a href="SUBMISSION.md" download>繳交說明 ↓</a><a href="scholar-atlas-source.zip" download>完整原始碼 ZIP ↓</a></div></div>`}
const input=(n,l,v='',t='text',required=false)=>`<label class="field">${l}<input name="${n}" type="${t}" value="${esc(v)}" ${required?'required':''} ${t==='number'?'min="1900" max="2200"':''}></label>`;
function editor(kind,x={}){if(!ws){toast('請先選取電腦資料夾');return}edit={kind,id:x.id};$('#dialogTitle').textContent=(x.id?'編輯':'新增')+(kind==='prof'?'教授資料':'論文與原文');$('#fields').innerHTML=kind==='prof'?input('name','教授姓名 *',x.name,'text',true)+input('school','學校',x.school)+input('program','Program／系所',x.program)+input('url','官方研究頁面',x.url,'url'):input('title','論文標題 *',x.title,'text',true)+input('year','所收錄版本的發表年份（可留空）',x.year||'','number')+input('url','原始論文／DOI 來源連結',x.url,'url')+`<label class="field">原文 PDF（50 MB 以下；掃描檔需先 OCR）<input name="pdf" type="file" accept=".pdf,application/pdf" ${x.hasPDF?'disabled':''}></label>${x.hasPDF?'<p class="hint">已保存原文。若要替換為不同版本，請新增一筆論文，以免破壞既有引用。</p>':''}<label class="check"><input name="authorship" type="checkbox" required ${x.authorship?'checked':''}>我已確認這位教授是論文作者之一，且有權保存所附 PDF。</label><p class="hint">只填來源連結也可保存，但沒有 PDF 就不能執行原文分析。</p>`;$('#editor').showModal()}
$('#editForm').onsubmit=async e=>{e.preventDefault();if(busy)return;let f=new FormData(e.target),p=current(),meta={};for(let k of edit.kind==='prof'?['name','school','program','url']:['title','url'])meta[k]=String(f.get(k)||'').trim();if(meta.url&&!safeUrl(meta.url)){toast('網址須為 HTTP／HTTPS');return}if(edit.kind==='prof'&&!meta.name||edit.kind==='paper'&&!meta.title){toast('請填寫必要欄位');return}if(edit.kind==='paper'){meta.year=f.get('year')?Number(f.get('year')):null;if(meta.year!==null&&(!Number.isInteger(meta.year)||meta.year<1900||meta.year>2200)){toast('年份無效');return}meta.authorship=f.get('authorship')==='on';if(!meta.authorship){toast('請確認作者與檔案使用權');return}if(p.papers.some(q=>q.id!==edit.id&&(q.title.toLowerCase()===meta.title.toLowerCase()||(meta.url&&q.url===meta.url)))){toast('此標題或來源連結已收錄');return}}await job('儲存資料…',async signal=>{if(edit.kind==='prof'){if(edit.id){Object.assign(p,meta);await ws.saveProfessor(p)}else{let added=await ws.addProfessor({...meta,notes:''});professors.push(added);selected=added.id;tab='papers'}}else{let old=p.papers.find(q=>q.id===edit.id),q={...old,...meta,id:edit.id||crypto.randomUUID(),hasPDF:old?.hasPDF||false},file=f.get('pdf'),pages=null;if(file?.size&&!old?.hasPDF){pages=await extractPDF(file,(n,total)=>progress(`擷取 PDF 第 ${n} / ${total} 頁`),signal);q.hash=await digest(await file.arrayBuffer());q.textHash=await digest(JSON.stringify(pages));if(p.papers.some(x=>x.id!==q.id&&x.hash===q.hash))throw Error('此 PDF 已收錄在同一位教授的資料夾');q.hasPDF=true;q.originalName=file.name;q.pageCount=pages.length;q.lowPages=pages.filter(x=>x.text.trim().length<30).map(x=>x.page);q.status='extracted'}if(!q.hasPDF&&!q.url)throw Error('請提供 PDF 或論文來源連結');if(signal.aborted)throw Error('已取消，未建立論文');if(old){if(file?.size&&!old.hasPDF){let dir=await ws.paperDir(p,q);await writeFile(dir,'original.pdf',file);await writeFile(dir,'pages.json',JSON.stringify(pages,null,2))}Object.assign(old,q);await ws.savePaper(p,old)}else await ws.addPaper(p,q,file?.size?file:null,pages)}$('#editor').close();toast('已寫入實體資料夾')})};
async function evidence(p,q,page=1,quote=''){let pages=await ws.pages(p,q);if(!Number.isInteger(page)||page<1||page>pages.length)throw Error('引用頁碼不在 PDF 範圍內');if(pdfURL)URL.revokeObjectURL(pdfURL);pdfURL=URL.createObjectURL(await ws.pdf(p,q));$('#evidenceTitle').textContent=q.title;$('#evidenceBody').innerHTML=`<div class="toolbar"><label>PDF 頁次 <select id="pageSelect">${pages.map(pg=>`<option value="${pg.page}" ${pg.page===page?'selected':''}>${pg.page} / ${pages.length}${pg.label!==String(pg.page)?'（標籤 '+esc(pg.label)+'）':''}</option>`).join('')}</select></label><a href="${pdfURL}" download="${esc(q.originalName)}">下載原始 PDF</a></div>${quote?`<blockquote>${esc(quote)}</blockquote><p class="hint">上方引文已在該頁擷取文字中核對；請閱讀上下文判斷結論是否成立。</p>`:''}<div class="evidence-grid"><iframe id="pdfFrame" title="PDF 原文" src="${pdfURL}#page=${page}"></iframe><div><h3>該頁擷取文字</h3><pre id="pageText">${esc(pages[page-1].text||'此頁沒有可擷取文字，需要先 OCR。')}</pre></div></div>`;$('#pageSelect').onchange=e=>{let n=Number(e.target.value);$('#pdfFrame').src=pdfURL+'#page='+n;$('#pageText').textContent=pages[n-1].text||'此頁沒有可擷取文字，需要先 OCR。'};$('#evidence').showModal()}
async function exportFolder(p){let entries=[];async function walk(dir,path){for await(let[n,h]of dir.entries()){if(h.kind==='directory')await walk(h,path+'/'+n);else entries.push([path+'/'+n,await h.getFile()])}}await walk(await ws.profDir(p),p.folder);download(p.folder+'.zip',await zip(entries));toast('已匯出磁碟中的完整教授資料夾')}
function requireModel(){if(!config.key||!config.model){view='model';render();toast('先設定 AI，再按「返回教授，繼續分析」。已匯入的資料不會遺失。');return false}return true}
document.addEventListener('click',async e=>{let b=e.target.closest('[data-act]');if(!b)return;e.preventDefault();if(busy){toast('目前正在處理，請等待或取消');return}let a=b.dataset.act,k=b.dataset.id,p=current(),q=p?.papers.find(x=>x.id===k);try{if(a==='setup-model'){view='model';await render()}if(a==='return-professor'){view='library';await render()}if(a==='go-synthesis'){tab='synthesis';await render()}if(a==='analyze-pending')await analyzePending(p);if(a==='import-folder')await chooseProfessorFolder();if(a==='connect')$('#connect').click();if(a==='add-prof')editor('prof');if(a==='edit-prof')editor('prof',p);if(a==='open'){selected=k;tab='papers';await render()}if(a==='back'){selected=null;await render()}if(a==='tab'){tab=k;await render()}if(a==='add-paper')editor('paper');if(a==='edit-paper')editor('paper',q);if(a==='read'||a==='cite')await evidence(p,q,Number(b.dataset.page||1),b.dataset.quote||'');if(a==='save-interests'){ws.settings.interests=$('#interests').value;await ws.saveSettings();toast('申請方向已儲存');await render()}if(a==='save-notes'){p.notes=$('#notes').value;await ws.saveProfessor(p);await writeFile(await ws.profDir(p),'application-notes.md',p.notes);toast('已儲存申請筆記')}if(a==='zip')await job('打包實體資料夾…',()=>exportFolder(p));if(a==='archive-paper'||a==='archive-prof'){if(confirm('將資料移至工作區的 trash 封存目錄？原始檔仍會保留在電腦，可自行取回。'))await job('封存資料…',async()=>{await ws.archive(p,a==='archive-paper'?q:null);professors=await ws.list();if(a==='archive-prof')selected=null})}if(a==='verify-key'){let key=$('#apiKey').value.trim()||config.key;if(!key)throw Error('請輸入 API key');await job('向 Gemini 驗證金鑰並查詢模型…',async signal=>{let found=await listModels(key,signal);models=found.filter(m=>!/(image|audio|tts|robotics)/i.test(m));if(!models.length)throw Error('此金鑰沒有可用的文字生成模型');config={key,model:models.find(m=>/flash/.test(m))||models[0]};toast('金鑰可讀取模型列表；可再測試模型（選用）')})}if(a==='clear-key'){config={key:'',model:''};models=[];render();toast('已清除本分頁金鑰')}if(a==='test-model'){if(!requireModel())return;await job('測試真實模型生成…',async signal=>{await generate(config,'這是連線測試。回傳 JSON：claims 為空陣列，gaps 為「連線成功」。',signal);toast('模型生成連線成功')})}if(a==='analyze'){if(!requireModel())return;await ws.pdf(p,q);let pages=await ws.pages(p,q),n=pages.filter(x=>x.text.trim()).length;if(!n)throw Error('這份 PDF 沒有可擷取文字，請先 OCR');if(!confirm(`將「${q.title}」共 ${pages.length} 頁的擷取文字送至 Google Gemini（${config.model}）分析，使用你的 API 額度。圖像本身不會送出。繼續？`))return;await job('準備原文分析…',async signal=>{let result=await analyzePaper({...config},q,pages,progress,signal);if(signal.aborted)throw Error('已取消，未覆寫分析');await ws.saveAnalysis(p,q,result,reportMarkdown(q.title,result,p.papers));toast('原文分析已儲存；請查看引用並核對語意')})}if(a==='analysis'){let result=await ws.analysis(p,q);if(!result)throw Error('找不到 analysis.json，請重新分析');currentResult=result;content.innerHTML=`<section class="hero"><div><div class="eyebrow"><a href="#" data-act="return-detail">← 返回論文</a></div><h1>${esc(q.title)}</h1><p>原文分析 · 引用片段已核對，推論仍需人工判斷</p></div><button data-act="download-analysis" data-id="${esc(q.id)}">↓ 下載分析</button></section>${reportHTML(result,p.papers)}`;}if(a==='return-detail')await render();if(a==='download-analysis'){let r=await ws.analysis(p,q);download(q.id+'-analysis.md',reportMarkdown(q.title,r,p.papers))}if(a==='download-synthesis'){let r=await ws.synthesis(p);download(p.name+'-synthesis.md',reportMarkdown(p.name+' 研究概要',r,p.papers))}if(a==='synthesize'){if(!requireModel())return;let ids=[...document.querySelectorAll('input[name="selectedPaper"]:checked')].map(x=>x.value);if(ids.length<2)throw Error('請至少選取兩篇已分析論文');if(ids.length>20)throw Error('每次最多選取 20 篇，避免超過模型上下文');if(!confirm(`將 ${ids.length} 篇論文的分析與原文引文，以及你的申請研究方向送至 Google Gemini，使用 API 額度。繼續？`))return;await job('載入已分析原文證據…',async signal=>{let docs=[];for(let id of ids){let paper=p.papers.find(x=>x.id===id),analysis=await ws.analysis(p,paper);if(!analysis||analysis.pdfHash!==paper.hash)throw Error('部分論文分析缺失或版本不符，請先重新分析');await ws.pdf(p,paper);docs.push({...paper,pages:await ws.pages(p,paper),analysis})}let result=await synthesize({...config},p,docs,ws.settings.interests,progress,signal);if(signal.aborted)throw Error('已取消，未覆寫概要');await ws.saveSynthesis(p,result,reportMarkdown(p.name+' 研究概要',result,p.papers));toast('跨論文概要已寫入教授資料夾')})}}catch(e){toast(e.message)}});render();

let pendingFolder=null;
async function chooseProfessorFolder(){
 if(!window.showDirectoryPicker){toast('請用桌面 Chrome／Edge 直接開啟 HTTPS 網站');return}
 try{
  const handle=await window.showDirectoryPicker({mode:ws?'read':'readwrite',id:'scholar-atlas-import'});
  if((await maybeJSON(handle,'workspace.json'))?.version===2){toast('這是既有研究庫，請按「開啟既有研究庫」，不要當作新的教授資料夾匯入');return}
  let scanned;
  await job('掃描教授資料夾…',async()=>{scanned=await scanFolder(handle)});
  if(!scanned)return;
  if(!scanned.files.length){toast('此資料夾沒有 PDF；現有 Scholar Atlas 研究庫請使用「開啟既有研究庫」');return}
  pendingFolder={handle,...scanned};
  $('#bulkName').value=handle.name;$('#bulkRights').checked=false;
  $('#bulkDestination').textContent=ws?'保存至目前開啟的研究庫。':'將在所選資料夾內建立 scholar-atlas-data 研究庫，保留原檔。';
  $('#bulkList').textContent=`找到 ${scanned.files.length} 份 PDF，忽略 ${scanned.ignored} 個其他檔案。教授名稱可修改；學校、年份與研究方向不會猜測。\n\n`+scanned.files.map(f=>f.path).join('\n');
  $('#bulk').showModal();
 }catch(e){if(e.name!=='AbortError')toast(e.name==='SecurityError'?'瀏覽器不允許選取資料夾。請用桌面 Chrome／Edge 直接開啟網站，不要使用嵌入預覽。':e.message)}
}
$('#bulkCancel').onclick=()=>{$('#bulk').close();pendingFolder=null};
$('#bulkForm').onsubmit=async e=>{
 e.preventDefault();if(busy||!pendingFolder)return;
 const name=$('#bulkName').value.trim();if(!name||!$('#bulkRights').checked)return;
 const source=pendingFolder;
 const matches=professors.filter(p=>p.name===name);
 if(matches.length>1){toast('存在多位同名教授，請修改名稱以避免合併錯誤');return}
 if(matches.length&&!confirm('同名教授已存在，將把 PDF 加入 '+name+' 的現有資料夾，重複 PDF 會略過。繼續？'))return;
 $('#bulk').close();pendingFolder=null;
 let results;
 await job('建立教授並匯入 PDF…',async signal=>{
  if(!ws){ws=await Workspace.open(source.handle);professors=await ws.list();$('#folderStatus').textContent=source.handle.name+'/scholar-atlas-data/';$('#refresh').hidden=false;$('#connect').textContent='切換研究庫'}
  const existing=professors.filter(p=>p.name===name);
  if(existing.length>1)throw Error('研究庫有多位同名教授，請改名後再匯入');
  if(existing.length&&!matches.length&&!confirm('此研究庫已有同名教授，將合併論文並略過重複 PDF。繼續？'))return;let p=existing[0];if(!p){p=await ws.addProfessor({name,school:'',program:'',url:'',notes:''});professors.push(p)}
  selected=p.id;view='library';tab='papers';
  results=await importPapers({ws,professor:p,files:source.files,extract:extractPDF,signal,progress});
 });
 if(results){$('#bulkResult').querySelector('h2').textContent='批次匯入結果';$('#bulkResultText').textContent=results.map(r=>`${r.status}｜${r.path}｜${r.message}`).join('\n');$('#bulkSummary').textContent=['成功','略過','失敗','未處理'].map(k=>k+' '+results.filter(r=>r.status===k).length).join(' · ');$('#bulkResult').showModal()}
};
$('#bulkResultClose').onclick=()=>$('#bulkResult').close();

function workflowPanel(p){
 const step=nextStep(p.papers,{modelReady:!!(config.key&&config.model),interests:ws.settings.interests});
 const count=p.papers.filter(q=>q.hasPDF).length,done=p.papers.filter(q=>q.analysisAt).length;
 return `<section class="panel next-step"><ol class="journey" aria-label="研究整理流程">${['匯入 PDF','設定 AI','逐篇分析','研究概要'].map((label,i)=>`<li ${step.stage===i+1?'aria-current="step"':''}><span>${i+1}</span>${label}</li>`).join('')}</ol><div class="resume-panel"><div><h2>下一步：${esc(step.label)}</h2><p>${esc(step.text)}</p><small class="hint">${count} 篇 PDF · ${done} 篇已分析 · ${config.key&&config.model?'AI 已設定':'AI 尚未設定（只影響分析）'}</small></div><button class="primary" data-act="${step.action}">${esc(step.label)} →</button></div></section>`;
}
async function analyzePending(p){
 if(!requireModel())return;
 const pending=p.papers.filter(q=>q.hasPDF&&!q.analysisAt);
 if(!pending.length){toast('沒有待分析的 PDF');return}
 if(!confirm(`將以下 ${pending.length} 篇論文的擷取文字傳送至 Google Gemini（${config.model}），使用你的 API 額度。可能分多次呼叫；金鑰不會寫入磁碟。\n\n${pending.map(q=>q.title).join('\n')}\n\n開始分析？`))return;
 const results=[],snapshot={...config};
 await job('準備批次分析…',async signal=>{
  for(let i=0;i<pending.length;i++){
   const q=pending[i];if(signal.aborted){for(const remaining of pending.slice(i))results.push({title:remaining.title,status:'未處理',message:'已取消'});break}
   try{
    await ws.pdf(p,q);const pages=await ws.pages(p,q);
    if(!pages.some(pg=>pg.text.trim()))throw Error('沒有可擷取文字，需先 OCR');
    const result=await analyzePaper(snapshot,q,pages,text=>progress(`${i+1}/${pending.length} · ${q.title}：${text}`),signal);
    if(signal.aborted)throw Error('已取消，未儲存此篇分析');
    await ws.saveAnalysis(p,q,result,reportMarkdown(q.title,result,p.papers));
    results.push({title:q.title,status:'成功',message:'分析及引用已儲存，仍需核對語意'});
   }catch(e){results.push({title:q.title,status:'失敗',message:e.message});
    // Stop on API/network failures instead of repeatedly making billable calls.
    for(const remaining of pending.slice(i+1))results.push({title:remaining.title,status:'未處理',message:'前一篇未完成；修正問題後可再次分析'});
    break;
   }
  }
 });
 $('#bulkSummary').textContent=['成功','失敗','未處理'].map(k=>k+' '+results.filter(r=>r.status===k).length).join(' · ');
 $('#bulkResultText').textContent=results.map(r=>`${r.status}｜${r.title}｜${r.message}`).join('\n');
 $('#bulkResult').querySelector('h2').textContent='批次分析結果';$('#bulkResult').showModal();
}
